function preferences(){const a=state.analysis;if(!a)return '';const amount=v=>v==null?'':String(v/100);return `<details class="needs-compact" id="my-needs"><summary><strong>我的需求</strong><span>想保留多少钱、如何安排预算？在这里选一下 · 可选</span></summary><form id="analysis-profile" class="task-body profile-form"><p class="muted">在这里选择你的资金安排；不知道的金额可以留空。示例只填表，保存后生效。</p><div class="actions"><button type="button" class="secondary" data-preset="careful">保留资金较多</button><button type="button" class="secondary" data-preset="flexible">保留资金较少</button></div><label>方案名称<input name="name" maxlength="30" value="${esc(a.profile.name)}" required></label><label>希望保留的余额（元）<input name="reserve" inputmode="decimal" placeholder="未知可留空" value="${amount(a.profile.reserve)}"></label><label>未来其他必要支出（元）<input name="upcoming" inputmode="decimal" placeholder="不含下方订阅，不含已付账单" value="${amount(a.profile.upcoming)}"></label><p class="muted">另行预留已知订阅 ¥${yuan(a.nextDebits)}。请勿重复计入上述金额；仅为下个周期安排，不推断收入。</p><label>10月1—12日总预算（元）<input name="budget" inputmode="decimal" placeholder="不是整月预算" value="${amount(a.profile.budget)}"></label><details><summary>同区间分类预算（可留空）</summary><div class="budget-inputs">${a.rows.map(r=>`<label>${esc(r.name)}<input name="budget-${r.name}" inputmode="decimal" value="${amount(r.budget)}" placeholder="未设置"></label>`).join('')}</div></details><button class="primary" ${busy?'disabled':''}>保存偏好并重新分析</button><p class="muted">更改偏好会开启新分析对话，避免把旧方案混进新结论。</p></form></details>`;}
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const yuan=v=>new Intl.NumberFormat('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2}).format(v/100);
const icons={shield:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6z"/><path d="m8 12 3 3 5-6"/>',home:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',chart:'<path d="M4 3v18h17M8 16v-5m5 5V6m5 10V9"/>',sub:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 10h18M8 3v4m8-4v4"/>',log:'<path d="M6 3h9l4 4v14H6zM14 3v5h5M9 12h7m-7 4h7"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',up:'<path d="M12 20V4m-6 6 6-6 6 6"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M16 11h5v5h-5zM5 5V3h12"/>',check:'<path d="m5 12 4 4L19 6"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.shield}</svg>`;
const labels={unavailable:'暂不能执行',superseded:'已补充',expired:'已过期',collecting:'请补充信息',approval:'待你批准',clarify:'待澄清',success:'已完成',blocked:'已拦截',rejected:'已否决',pending:'待核对'};
const badge=status=>`<span class="badge ${esc(status)}">${labels[status]||esc(status)}</span>`;
let state,view=(['home','bills','calendar','subscriptions','profile','deposit'].includes(new URLSearchParams(window.location.search).get('view'))?new URLSearchParams(window.location.search).get('view'):'home'),selected=new URLSearchParams(window.location.search).get('task')||null,busy=false,fault='none',toastTimer,analysisError='',analysisDraft='',homePending='',homeChatError='',homeReplyReady=false;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
async function api(path,data){try{return await requestJSON(path,data,{userId:state?.user?.id||''});}catch(e){if(e.status===401){const wasLoggedIn=Boolean(state);state=null;renderLogin(wasLoggedIn?e.message:'');e.auth=true;}throw e;}}
async function refresh(){state=await api('/api/state');render();}
const task=()=>state.tasks.find(t=>t.id===selected);
function connectionPanel(){const c=state.chatgpt||{};return `<section class="panel" style="padding:18px;margin-top:16px"><strong>ChatGPT 账号连接</strong><p style="margin:8px 0;font-size:13px">${c.connected?`${esc(c.email)} · ${c.verified?'模型调用已验证':'已登录，尚未验证模型调用'}`:'使用你的 ChatGPT 账号授权 FinGuard 理解指令。登录后，输入的指令与演示联系人会发送至 OpenAI，并使用账号额度。'}</p><div class="actions">${c.connected?`<button class="secondary" id="gpt-models">刷新模型</button><select id="gpt-model" aria-label="选择 GPT 模型">${(c.models||[]).map(m=>`<option value="${esc(m.slug)}" ${m.slug===c.model?'selected':''}>${esc(m.name)}</option>`).join('')}</select><button class="primary" id="gpt-test">测试连接</button><button class="secondary" id="gpt-logout">断开连接</button>`:'<button class="primary" id="gpt-login">Continue with ChatGPT</button>'}</div><small class="muted">授权仅保存在本次程序运行中；重启后重新登录。模拟转账仍需逐笔批准。</small></section>`;}
function bindConnection(){for(const [id,path] of [['gpt-models','models'],['gpt-test','test'],['gpt-logout','logout']]){const el=document.getElementById(id);if(el)el.onclick=async()=>{if(busy)return;el.disabled=true;try{await api('/api/chatgpt/'+path,{});await refresh();toast(path==='test'?'GPT 真实调用测试成功':'连接状态已更新');}catch(e){toast(e.message);}finally{el.disabled=false;}};}
  const login=$('#gpt-login');if(login)login.onclick=async()=>{login.disabled=true;try{const result=await api('/api/chatgpt/login',{});window.location.assign(result.url);}catch(e){toast(e.message);login.disabled=false;}};
  const picker=$('#gpt-model');if(picker)picker.onchange=async()=>{try{await api('/api/chatgpt/model',{model:picker.value});await refresh();}catch(e){toast(e.message);}};
}
function renderLogin(error=''){
 $('#app').innerHTML=`<main class="login-shell"><section class="login-intro"><div class="brand"><span class="brand-icon">${icon('shield')}</span>FinGuard</div><span class="eyebrow">FINGUARD · V1.0</span><h1>个人银行</h1><p>智能转账、账单分析与订阅管理。<br>在独立的模拟空间里，放心体验。</p><div class="login-features">✓ 每个账号独立保存记录<br>✓ 重要操作仍需明确确认<br>✓ 全部资金与交易都是模拟</div></section><section class="login-card"><span class="pill">邀请内测</span><h2>登录你的测试账号</h2><p class="muted">使用管理员分配的账号和密码登录。敏感业务另需验证。</p><form id="account-login"><label>测试账号<input id="login-user" name="username" autocomplete="username" maxlength="32" placeholder="例如 tester" required></label><label>密码<input id="login-password" name="password" type="password" autocomplete="current-password" maxlength="128" required></label><p id="login-error" role="alert">${esc(error)}</p><button class="primary" id="login-submit">登录 FinGuard</button></form><p class="muted">普通账户由管理员分配；独立体验账户可从上方入口创建。忘记密码请联系管理员。<br>登录最多保持7天；共用电脑使用完请退出。</p></section></main>`;
 $('#account-login').addEventListener('submit',async e=>{e.preventDefault();const button=$('#login-submit');button.disabled=true;button.textContent='正在登录…';try{await api('/api/auth/login',{username:$('#login-user').value,password:$('#login-password').value});selected=null;homeChatError='';homeReplyReady=false;homePending='';view='home';analysisDraft='';analysisError='';await refresh();}catch(e){renderLogin(e.message);}});
 const loginForm=$('#account-login');
 fetch('/api/health').then(r=>r.ok?r.json():null).then(data=>{
  if(loginForm!==$('#account-login'))return;
  if(data?.reviewDemo){
   const entry=document.createElement('div');entry.className='review-space-entry';entry.innerHTML='<button type="button" class="primary" id="create-review-space">创建独立体验账户</button><p class="muted">独立余额与记录；自行设置支付密码和手机验证器。</p>';
   loginForm.before(entry);$('#create-review-space').onclick=()=>openReviewSpace(enterReviewSpace);
   document.querySelector('.login-card > .pill').textContent='模拟银行体验';document.querySelector('.login-card > h2').textContent='进入 FinGuard';document.querySelector('.login-card > p.muted').textContent='首次体验请创建独立账户，已有账户可直接登录。';
  }
  if(!data?.demoLogin)return;
  const info=document.createElement('p');info.className='muted';info.id='demo-login-info';info.innerHTML='演示测试账号 <strong>tester</strong> · 密码 <strong>tester</strong><br>共享模拟账户，请勿填写个人资料。<br><button type="button" class="secondary" id="fill-demo-login">填入测试账号</button>';
  loginForm.after(info);$('#fill-demo-login').onclick=()=>{$('#login-user').value='tester';$('#login-password').value='tester';$('#login-submit').focus();};
 }).catch(()=>{});
}
async function enterReviewSpace(){state=null;selected=null;homeChatError='';homeReplyReady=false;homePending='';view='home';analysisDraft='';analysisError='';window.history.replaceState(null,'','/?view=home');try{await refresh();}catch{renderLogin('体验账户已创建，请使用已保存的登录资料重新登录，或刷新页面。');}}
function render(){
 const modalWasOpen=Boolean($('#approval-dialog')?.open);
  if(!state)return renderLogin();
  const names={profile:'个人中心',records:'交易记录',contacts:'收款人通讯录',planning:'我的计划',calendar:'每日收支日历',deposit:'模拟转入',anomaly:'扣费核对中心',home:'账户首页',bills:'账单',subscriptions:'订阅管理',evidence:'操作证据',pending:'待办中心'};
  $('#app').innerHTML=`${navigationHTML({section:['bills','calendar','subscriptions'].includes(view)?'bills':'home',name:displayName(),pending:pendingCount(state)})}<div class="shell"><main class="main"><section class="welcome"><div><div class="eyebrow">FINGUARD / PERSONAL BANKING</div><h1>${view==='home'?esc(displayName())+'，你好。':names[view]}</h1><p>${view==='home'?new Date().toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'long',day:'numeric',weekday:'long'}):view==='bills'?'查看收支明细和待核对扣费。':view==='subscriptions'?'查看有效订阅和扣费记录。':view==='profile'?'管理个人资料、资金安排与账户安全。':view==='planning'?'设置你的预算、储蓄目标和特殊开销。':view==='calendar'?'查看每日记录，安排接下来的花费。':'查看记录，核对每一步操作。'}</p></div><span class="account-mode">模拟账户</span></section>${['bills','calendar','subscriptions'].includes(view)?billNavigation():''}${view==='profile'?profileView():view==='records'?ordersView():view==='contacts'?contactsView():view==='planning'?planningView():view==='calendar'?calendarView():view==='deposit'?depositView():view==='home'?home():view==='bills'?bills():view==='subscriptions'?subscriptions():view==='pending'?pendingView():view==='anomaly'?anomalyView():evidence()}<footer class="footnote"><span>FinGuard · 所有账户、交易与订阅均为模拟，未连接真实银行。</span><details class="quiet-help"><summary>账户说明</summary><p>这里是模拟账户，资金与交易不会进入真实银行。</p></details></footer></main></div>${approvalDialog(task())}`;
  bindNavigation(document.querySelector('.site-header'));
  if(state.user?.username==='tester')fetch('/api/health').then(r=>r.json()).then(data=>{const target=document.querySelector('.welcome > .account-mode');if(data.reviewDemo&&target&&state?.user?.username==='tester'){target.innerHTML='<button class="mini-link" id="new-review-space">创建独立体验账户 →</button>';document.querySelector('#new-review-space').onclick=()=>openReviewSpace(enterReviewSpace);}}).catch(()=>{});
  document.querySelectorAll('[data-open-cashflow]').forEach(b=>b.onclick=()=>openCashflowReview(api,refresh));
  document.querySelectorAll('[data-open-funding]').forEach(b=>b.onclick=()=>openFundingAssistant(api,refresh));
  document.querySelectorAll('[data-nav]').forEach(el=>el.onclick=e=>{e.preventDefault();if(el.dataset.nav==='deposit'){openDeposit();return;}if(el.dataset.nav==='pending'){openPending();return;}if(el.dataset.nav==='records'){openOrders();return;}view=el.dataset.nav;if(view==='bills')billTab='ledger';window.history?.replaceState(null,'','/?view='+view);contactEdit='';expenseEdit='';goalEdit='';render();if(['bills','calendar'].includes(view))syncLedger(true);});
  document.querySelectorAll('[data-prompt]').forEach(el=>el.onclick=()=>send(el.dataset.prompt));
  document.querySelectorAll('[data-task]').forEach(el=>el.onclick=()=>{selected=el.dataset.task;if(view!=='evidence')view='home';render();if(task()?.status==='approval')$('#approval-dialog')?.showModal();});
  document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>act(el.dataset.action,el.dataset.value));
  $('#logout').onclick=async()=>{if(busy)return;try{await api('/api/auth/logout',{});state=null;selected=null;analysisDraft='';analysisError='';view='home';$('#demo-reset-dialog')?.close();renderLogin();}catch(e){toast(e.message);}};
  bindAnalysis();bindBudgetSettings(document,api,refresh);bindUseFields($('#approval-dialog')||document,async row=>{if(busy)return;busy=true;try{await api('/api/tasks/'+task().id+'/use',readUse(row));await refresh();}catch(e){toast(e.message);}finally{busy=false;render();}});
  $('#edit-needs')?.addEventListener('click',()=>{view='planning';render();const el=$('#my-needs');if(el){el.open=true;el.scrollIntoView({block:'start'});}});
  document.querySelectorAll('[data-bill-tab]').forEach(el=>el.onclick=()=>{if(el.dataset.billTab==='review'){openAnomaly();return;}billTab=el.dataset.billTab;view='bills';render();});
  bindAnomaly();bindFeatures();bindProfile();bindLedger(state,render,()=>syncLedger(true),api);bindExpenseChart(document.getElementById('analysis-expense-chart'),(state.analysis?.records||[]).map(r=>({...r,kind:'expense'})),JSON.stringify([state.user?.id,'sample-analysis']));if(modalWasOpen&&$('#approval-dialog'))$('#approval-dialog').showModal();
  const messages=$('.analysis-messages');if(view==='bills'&&messages){const turns=messages.querySelectorAll('.analysis-turn');if(turns.length>1)messages.scrollTop=turns[turns.length-1].offsetTop-turns[0].offsetTop;}
  $('#reset').onclick=()=>openDemoReset(api,async()=>{selected=null;view='home';fault='none';analysisError='';await refresh();});
  document.querySelector('[data-home-reply]')?.addEventListener('click',revealHomeReply);
  $('#message-form')?.addEventListener('submit',e=>{e.preventDefault();send($('#message').value);});
  $('#message')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('#message-form').requestSubmit();}});
  $('#fault')?.addEventListener('change',e=>{fault=e.target.value;});
  $('#show-evidence')?.addEventListener('click',()=>{const t=task();if(!t)return;openDialog({title:'交易详情',content:`<h3>${esc(t.message)}</h3><p>${esc(t.summary)}</p><p>申请时间：${new Date(t.createdAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})}</p>${t.result?.time?`<p>完成时间：${new Date(t.result.time).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})}</p>`:''}<details class="receipt-references"><summary>查看交易凭证</summary>${t.result?.id?`<p>回执：${esc(t.result.id)}</p>`:''}<p>参考编号：${esc(t.id)}</p></details>`});});
}
function stats(){const active=state.subscriptions.filter(s=>s.status==='active');return `<div class="stats"><button class="stat dark" data-nav="bills"><span class="stat-label">模拟账户 · 可用余额</span><span class="stat-symbol">${icon('wallet')}</span><div class="stat-value"><small>¥</small>${yuan(state.balance)}</div><div class="stat-note">本地样例账户 · 尾号 2026 · 查看分析 →</div></button><button class="stat" data-nav="subscriptions"><span class="stat-label">下个周期已知代扣</span><span class="stat-symbol">${icon('sub')}</span><div class="stat-value"><small>¥</small>${yuan(active.reduce((a,s)=>a+s.cents,0))}</div><div class="stat-note">${active.length} 项仍在自动续费 · 按样例固定价格估算</div></button><button class="stat" data-nav="pending"><span class="stat-label">待你处理</span><span class="stat-symbol">${icon('shield')}</span><div class="stat-value">${state.counts.pending}<small> 项</small></div><div class="stat-note">只显示尚需处理的事项 · 去处理 →</div></button></div>`;}
function conversationView(){const t=task();return `<section class="panel"><div class="panel-head"><h2>金融助手</h2><span class="pill ${state.planner==='local'?'amber':''}">${state.planner==='model'?'AI 助手':'基础助手'}</span></div><div class="conversation">${t?`${(t.dialogue||[]).slice(0,-2).map(m=>`<div class="chat-history ${m.role}">${m.role==='user'?'你':'FinGuard'}：${esc(m.content)}</div>`).join('')}<div class="user-label">你的目标</div><div class="bubble">${esc(t.message)}</div>`:''}<div class="assistant-heading"><span class="small-logo">${icon('shield')}</span>FinGuard <small class="muted">${t?'任务助手':''}</small></div><div class="assistant-copy" id="home-latest-reply"><p>${t?esc(t.summary):'说出你的目标，我会先列明金额、时间和条件。每一份计划，都由你确认后执行。'}</p>${!t?'<p class="muted" style="font-size:13px">例如：安排给家人的转账，先留足生活费。</p>':''}</div>${homePending?`<div class="bubble">${esc(homePending)}</div>`:''}${busy?'<div class="status-line" role="status"><span class="spinner"></span><span class="muted">正在理解你的问题…</span></div>':''}${!t?`<div class="suggestions">${[['帮我统一资金安排','一起安排接下来的钱','付款、生活费、目标与闲钱一起核对'],['给小林转200元','转账给熟悉的人','先核对收款人，再由你批准'],['分析本月账单','看看这个月的钱花在哪里','分类合计与疑似重复扣费'],['看看我的订阅','整理自动续费','查看扣费证据，选择需要停止的代扣'],['帮我安排闲钱理财','安排我的闲钱','结合用钱时间、必要支出和风险比较产品'],['记一笔开销','用对话记账','告诉我发生了什么，不必逐项填表']].map(([p,a,b])=>`<button class="suggestion" data-prompt="${p}" ${busy?'disabled':''}><div><span>${a}</span><small>${b}</small></div>${icon('arrow')}</button>`).join('')}</div>`:'<button class="mini-link" data-action="new">开始一个新目标 →</button>'}</div><div class="home-chat-feedback" role="status">${homeReplyReady?'FinGuard 已回复':''}${homeReplyReady?'<button type="button" data-home-reply>查看最新回复 ↓</button>':''}</div>${homeChatError?`<p class="home-chat-error" role="alert">${esc(homeChatError)}</p>`:''}<form class="composer" id="message-form"><div class="input-row"><textarea id="message" aria-label="告诉FinGuard你的目标" placeholder="例如：给小陈转200元" rows="2" maxlength="600" ${busy?'disabled':''}></textarea><button class="send" aria-label="发送目标" ${busy?'disabled':''}>${icon('up')}</button></div><div class="composer-foot">Enter 发送 · Shift + Enter 换行</div><details class="fault-details"><summary>异常恢复演示</summary><div class="fault-line"><label for="fault">异常恢复演示</label><select id="fault" ${busy?'disabled':''}><option value="none" ${fault==='none'?'selected':''}>正常执行</option><option value="lost_response" ${fault==='lost_response'?'selected':''}>执行成功，但响应丢失</option><option value="before_execution" ${fault==='before_execution'?'selected':''}>执行前超时</option></select></div></details></form></section>`;}
function home(){const t=task(),appointments=(state.bankPlans||[]).filter(p=>p.status==='scheduled');return `<div class="home-columns"><section class="home-account" aria-label="账户概览">${pendingStrip()}${balanceStrip()}${budgetOverviewHTML(state.personal.budget)}${fundingEntryHTML(state.funding)}${cashflowEntryHTML(state.cashflow)}<section class="home-scheduled"><div class="editorial-heading"><h2>已预约</h2><a class="mini-link" href="/banking.html#appointments">管理 →</a></div>${appointments.slice(0,3).map(p=>`<a class="appointment-row" href="/banking.html#appointments"><strong>${esc(p.title)}</strong><small>${esc(p.steps.find((x,i)=>p.runs[i].status==='waiting')?.date||'待执行')}</small></a>`).join('')||'<p class="muted">暂无预约转账。</p>'}</section><div class="home-risk">${anomalySummary()}</div></section><aside class="home-assistant" aria-label="金融助手">${conversationView()}${t&&t.action!=='chat'?`<section class="panel task-body home-current-task"><h2>当前事项</h2>${badge(t.status)}${taskPanel(t)}</section>`:''}</aside></div>`;}
function taskPanel(t){if(t.action==='chat')return '<p class="muted">正常聊天无需批准，不会改变资金或订阅。可以继续在对话框提问。</p>';if(t.action==='contacts')return `<div class="contact-grid">${state.contacts.map(c=>`<button class="candidate" data-contact-pay="${c.id}"><strong>${esc(c.name)} · ${esc(c.alias)}</strong><small>尾号 ${esc(c.tail)} · 点击转账</small></button>`).join('')}</div><button class="secondary" data-nav="contacts">管理收款人</button>`;let html=`<h3>${{deposit:'资金转入',transfer:'转账',cancel:'停止代扣',bills:'账单分析',subscriptions:'订阅概览'}[t.action]||'目标检查'}</h3>`;
  if(t.steps)html+=`<details class="quiet-help" ${t.status==='success'?'':'open'}><summary>处理过程</summary><ol class="steps">${t.steps.map((s,i)=>`<li><span class="step-index">${t.status==='success'?'✓':i+1}</span>${esc(s)}</li>`).join('')}</ol></details>`;
  if(t.status==='clarify')html+=`<div class="notice">收款人存在重名，请选择正确对象。</div>${t.candidates.map(c=>`<button class="candidate" data-action="clarify" data-value="${c.id}" ${busy?'disabled':''}><strong>${esc(c.name)}</strong><small>${esc(c.description)} · 尾号 ${c.tail}</small></button>`).join('')}<div class="actions"><button class="secondary" data-action="reject" ${busy?'disabled':''}>否决这个任务</button></div>`;
  if(t.status==='approval')html+=`<div class="confirm-box"><h3>等待你核对</h3><p>${t.action==='cancel'?esc(t.subscription?.name):'¥'+yuan(t.params.cents)}</p><button class="primary" id="open-approval">打开确认窗口</button></div>`;
  if(t.status==='collecting')html+=`<div class="notice">${esc(t.summary)}</div><p class="muted">直接在对话框补充信息，尚未执行任何操作。</p><button class="secondary" data-action="reject">取消这个目标</button>`;
  if(t.status==='pending')html+=`<div class="notice">${esc(t.summary)}</div><div class="actions"><button class="primary" data-action="reconcile" ${busy?'disabled':''}>核对原操作结果</button></div>`;
  if(['blocked','rejected','unavailable','expired','superseded'].includes(t.status))html+=`<div class="notice">${esc(t.summary)}</div>`;
  if(t.status==='success'&&['transfer','cancel','deposit'].includes(t.action))html+=`<div class="receipt"><h3>✓ 已核对执行结果</h3><p>${esc(t.summary)}</p><p class="receipt-date">${new Date(t.result.time).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})}</p>${['transfer','deposit'].includes(t.action)?`<p>执行前 ¥${yuan(t.result.before)} → 执行后 ¥${yuan(t.result.after)}</p>`:''}</div>`;
  if(t.status==='success'&&t.action==='bills')html+=`<div class="report-mini">${chart(t.result)}${t.result.anomalies.map(a=>`<div class="notice">${esc(a.merchant)}：${esc(a.reason)}<br>来源：${a.ids.map(esc).join('、')}</div>`).join('')}</div>`;
  if(t.status==='success'&&t.action==='subscriptions')html+=t.result.map(s=>`<div class="result-sub"><span>${esc(s.name)}<br><small class="muted">¥${yuan(s.cents)}/月 · ${s.status==='active'?'代扣有效':'已停止'}</small></span>${s.status==='active'?`<button class="secondary" data-prompt="停止${esc(s.name)}代扣">申请停止</button>`:''}</div>`).join('');
  html+=`<div style="margin-top:12px"><button id="show-evidence" class="mini-link">查看交易详情 →</button></div>`;return html;}
function activity(){return `<section class="panel activity"><div class="panel-head"><h2>最近的目标</h2><button class="mini-link" data-nav="evidence">查看全部证据 →</button></div><div class="activity-list">${state.tasks.length?state.tasks.slice(0,5).map(t=>activityRow(t)).join(''):'<div class="activity-empty">还没有操作。从上方选择一个目标开始。</div>'}</div></section>`;}
function activityRow(t){return `<button class="activity-row" data-task="${t.id}"><span class="activity-icon">${icon(t.action==='transfer'?'arrow':t.action==='bills'?'chart':t.action==='cancel'?'sub':'log')}</span><span class="activity-info"><span class="activity-title">${esc(t.message)}</span><small>${new Date(t.createdAt).toLocaleString('zh-CN',{hour12:false})} · ${t.mode==='model'?'模型规划':'本地规划'}</small></span>${badge(t.status)}</button>`;}
function chart(report){return `<div class="muted" style="font-size:11px">${esc(report.period)}</div>${Object.entries(report.categories).sort((a,b)=>b[1]-a[1]).map(([cat,cents])=>`<div class="chart-row"><span>${esc(cat)}</span><span class="bar"><i style="width:${report.total?cents/report.total*100:0}%"></i></span><strong>¥${yuan(cents)}</strong></div>`).join('')}`;}
function pendingView(){const list=state.tasks.filter(t=>['approval','clarify','pending','collecting'].includes(t.status)),plans=(state.bankPlans||[]).filter(p=>['approval','paused','invalidated'].includes(p.status));return `<section class="panel"><div class="panel-head"><h2>待我处理</h2><span>${list.length+plans.length} 项</span></div><div class="activity-list">${list.map(activityRow).join('')}${plans.map(p=>`<button class="pending-item" data-bank-plan="${esc(p.id)}"><strong>${esc(p.title)}</strong><span>${({approval:'待确认',paused:'已暂停',invalidated:'授权失效'})[p.status]}</span></button>`).join('')}${!list.length&&!plans.length?'<p class="activity-empty">暂无需要你处理的事项。</p>':''}</div></section><div class="actions"><a href="/banking.html#appointments">查看已预约</a><a href="/banking.html#history">查看处理记录</a></div>`;}

const reviewNames={pending:'待核对',contacted:'已联系，等待回复',normal:'已核对为正常',resolved:'已记录处理结果'};
let activeAnomaly=null,billTab='ledger',analysisMobile='facts';
function anomalySummary(){const list=state.analysis?.anomalies||[];if(!list.length)return '';return list.map(x=>{const r=state.reviews?.[x.ids[0]],closed=['normal','resolved'].includes(r?.status);return `<section class="risk-banner ${closed?'risk-closed':''}"><div><span class="risk-kicker">${closed?'已记录 · 可重新核对':'需要关注 · 疑似重复扣费'}</span><h3>${esc(x.merchant)} · ${x.ids.length} 笔同日同金额扣费</h3><p>每笔 ¥${yuan(x.cents)}，可能重复部分 ¥${yuan(x.cents*(x.ids.length-1))}。${r?esc(reviewNames[r.status]):'尚未确认多扣，先核对订单。'}</p></div><button class="primary" data-open-anomaly="${esc(x.ids[0])}">${closed?'查看处理记录':'查看证据并处理'} ${icon('arrow')}</button></section>`;}).join('');}
function anomalyView(){const a=state.analysis.anomalies.find(x=>x.ids[0]===activeAnomaly)||state.analysis.anomalies[0];if(!a)return '<section class="panel"><div class="task-body"><h2>暂无待核对扣费</h2><p>当前规则未发现同日、同商户、同金额的记录。</p></div></section>';activeAnomaly=a.ids[0];const r=state.reviews?.[activeAnomaly]||{status:'pending',note:'',history:[]},rows=state.analysis.records.filter(x=>a.ids.includes(x.id));return `
<div class="case-heading"><div><span class="eyebrow">CHARGE REVIEW · ${esc(activeAnomaly)}</span><h2>${esc(a.merchant)}扣费核对</h2><p class="muted">同日同金额只是线索。核对订单和退款记录后，再记录结果。</p></div><span class="pill">${esc(reviewNames[r.status])}</span></div>
${state.analysis.anomalies.length>1?`<div class="actions">${state.analysis.anomalies.map(x=>`<button class="secondary" data-open-anomaly="${esc(x.ids[0])}">${esc(x.merchant)} · ${esc(x.ids[0])}</button>`).join('')}</div>`:''}
<div class="stats"><div class="stat"><span class="stat-label">该组扣费合计</span><div class="stat-value">¥${yuan(a.cents*a.ids.length)}</div></div><div class="stat"><span class="stat-label">可能重复部分</span><div class="stat-value caution">¥${yuan(a.cents*(a.ids.length-1))}</div><small>待核实，不是已确认的退款金额</small></div><div class="stat"><span class="stat-label">处理方式</span><h3 class="case-mode">选择外部核对结果</h3><small>不会自动退款或停止代扣</small></div></div>
<div class="case-grid"><section class="panel"><div class="panel-head"><h2>01 · 原始扣费证据</h2></div><div class="task-body"><div class="charge-pair">${rows.map(x=>`<article><span class="pill">${esc(x.id)}</span><h3>${esc(x.merchant)}</h3><strong>¥${yuan(x.cents)}</strong><p>${esc(x.date)} · ${esc(x.category)}</p></article>`).join('')}</div><p class="muted">这些是合成样例。当前没有商户订单号或银行退款回执，不能据此确定为何出现两笔。</p></div><div class="panel-head"><h2>02 · 建议核对顺序</h2></div><div class="task-body"><ol class="review-checklist"><li><strong>查订单</strong><p>检查是否购买了两个账号、两份权益，或存在补扣。</p></li><li><strong>查退款</strong><p>核对是否已有冲正或退款，避免重复申请。</p></li><li><strong>联系商户或支付服务方</strong><p>提供日期、金额及订单号，询问扣费依据和处理进度。</p></li></ol><div class="actions"><button class="secondary" data-draft="${esc(activeAnomaly)}">下载核对材料</button><button class="secondary" data-nav="subscriptions">查看订阅与停止代扣入口</button></div><p class="muted">停止后续代扣不等于退回已扣的钱；仍需另行批准。</p></div></section>
<section class="panel"><div class="panel-head"><h2>03 · 补充外部核对情况</h2></div><form id="review-form" class="task-body profile-form"><fieldset class="review-choices"><legend>选择核对结果</legend>${[['checking','pending','还没核实，继续核对'],['contacted','contacted','已联系商户，等待回复'],['separate','normal','已确认是不同订单'],['refund','resolved','已查到退款或冲正记录']].map(([v,status,label])=>`<label><input type="radio" name="outcome" value="${v}" data-status="${status}" required ${r.status===status?'checked':''}>${label}</label>`).join('')}</fieldset><label>补充说明（可选）<textarea name="note" maxlength="400" rows="3" placeholder="例如：已确认对应两个不同订单；或已联系商户，等待回复。请勿填写密码和完整银行卡号。">${esc(r.note||'')}</textarea></label><p class="muted">选择结果即可保存，说明可不填。记录以你的核对为依据，不会自动退款或改变余额。</p><button class="primary">保存处理记录</button><p id="review-feedback" role="status"></p></form><div class="panel-head"><h2>处理时间线</h2></div><div class="task-body">${(r.history||[]).length?[...r.history].reverse().map(h=>`<article class="event"><h3>${esc(reviewNames[h.status])}</h3><small>${new Date(h.time).toLocaleString('zh-CN')}</small><p class="case-note">${esc(h.note||'未填写说明')}</p></article>`).join(''):'<p class="muted">还没有处理记录。保存后会在这里显示。</p>'}</div></section></div>`;}
function openAnomaly(id){if(id)activeAnomaly=id;const d=openDialog({id:'anomaly-dialog',title:'扣费核对',wide:true,content:anomalyView()});bindAnomaly();bindAnalysis();return d;}
function bindAnomaly(){document.querySelectorAll('[data-open-anomaly]').forEach(el=>el.onclick=()=>{openAnomaly(el.dataset.openAnomaly);});$('#review-form')?.addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button.primary');button.disabled=true;try{const data=new FormData(e.target);await api('/api/analysis/review',{id:activeAnomaly,status:e.target.querySelector('[name=outcome]:checked').dataset.status,outcome:data.get('outcome'),note:data.get('note')});document.querySelector('#anomaly-dialog')?.close();await refresh();showResult('核对记录已保存',['仅更新核对记录，账户余额未改变。']);}catch(error){$('#review-feedback').textContent=error.message;button.disabled=false;}});}
function billNavigation(){return `<div class="section-navigation"><nav aria-label="账单内容">${[['bills','账单'],['calendar','日历'],['subscriptions','订阅']].map(([key,label])=>`<button type="button" data-nav="${key}" ${view===key?'aria-current="page" class="active"':''}>${label}</button>`).join('')}</nav><div class="section-tools">${view==='bills'?`<button class="mini-link" data-bill-tab="${billTab==='overview'?'ledger':'overview'}">${billTab==='overview'?'返回账单':'消费分析'}</button>`:''}<button class="mini-link" data-bill-tab="review">异常核对</button><button class="mini-link" data-open-imports>导入账单</button></div></div>`;}
function bills(){return billTab==='overview'?billOverview():ledgerView(state);}
function billOverview(){const a=state.analysis;if(!a)return oldBills();return `
<div class="analysis-hero"><div><h2>账单与收支</h2><p>消费明细、分类统计与预算核对。</p></div><span class="pill">只读分析 · 不执行资金操作</span></div>
<div class="analysis-mobile-tabs" role="group" aria-label="账单分析区域"><button type="button" data-analysis-pane="facts" aria-pressed="${analysisMobile==='facts'}">账单与预算</button><button type="button" data-analysis-pane="chat" aria-pressed="${analysisMobile==='chat'}">AI 分析</button></div>
<div class="bill-analysis-workspace" data-mobile-pane="${analysisMobile}"><section class="bill-analysis-main" aria-label="账单与预算">${anomalySummary()}
<div class="stats analysis-stats"><div class="stat"><span class="stat-label">当前模拟余额</span><div class="stat-value">¥${yuan(a.balance)}</div><small>不重复扣除历史消费</small></div><div class="stat"><span class="stat-label">样例区间支出</span><div class="stat-value">¥${yuan(a.total)}</div><small>2026.10.01—10.12 · 非完整月份</small></div><div class="stat ${a.headroom!==null&&a.headroom<0?'shortfall':''}"><span class="stat-label">预留后规划余量</span><div class="stat-value">${a.headroom===null?'待补充':`¥${yuan(a.headroom)}`}</div><small>余额 − 保留金额 − 未来其他支出 − 已知订阅</small></div></div>
${expenseChartHTML(a.records.map(r=>({...r,kind:'expense'})),{id:'analysis-expense-chart',title:'样例消费分类占比',subtitle:'2026.10.01—10.12 · 非完整月份'})}
<div class="actions"><button class="secondary" id="analysis-budget-open">查看分类与预算依据</button><button class="secondary" id="analysis-records-open">查看原始样例明细</button></div><p class="muted section-space">${esc(a.limits)}</p></section><aside class="bill-analysis-assistant" aria-label="AI账单助手"><section class="panel analysis-chat-panel"><div class="panel-head"><h2>和 FinGuard 聊账单</h2><button class="mini-link" id="edit-needs">设置我的需求</button><button class="mini-link" id="clear-analysis">新对话</button></div><div class="analysis-messages" aria-live="polite">${(state.advice||[]).length?state.advice.map(m=>`<article class="analysis-turn"><div class="user-label">你的问题</div><div class="bubble">${esc(m.question)}</div><span class="pill ${m.mode==='local'?'amber':''}">${m.mode==='model'?'AI 分析':'本地数据分析'}</span><time class="analysis-reply-time">${new Date(m.createdAt).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}</time><small class="mode-note">${esc(m.notice)}</small><p class="answer-text">${esc(m.answer)}</p><details><summary>本次回答的计算依据（当时快照）</summary><p class="muted">余额 ¥${yuan(m.facts.balance)}；区间支出 ¥${yuan(m.facts.total)}；方案 ${esc(m.facts.profile.name)}；${new Date(m.createdAt).toLocaleString('zh-CN')}</p></details></article>`).join(''):'<p class="muted">可以问“餐饮花得多吗”“为什么会员扣了两次”“按我的余额该怎么调整”。可在个人中心的预算设置中选填预算，建议会更具体。</p>'}${busy?'<p class="status-line"><span class="spinner"></span>正在结合账单和你的预算分析…</p>':''}${analysisError?`<p class="notice" role="alert">${esc(analysisError)}</p>`:''}</div><div class="analysis-prompts">${['哪些消费超预算？','餐饮哪几笔最多？','我的余额够不够？','会员为什么扣了两次？','花得太少需要增加吗？'].map(q=>`<button class="secondary" data-ask="${q}" ${busy?'disabled':''}>${q}</button>`).join('')}</div><form id="analysis-form" class="composer"><div class="input-row"><textarea id="analysis-question" aria-label="账单问题" placeholder="继续追问，我会保留这段分析上下文" maxlength="600" rows="2" ${busy?'disabled':''}>${esc(analysisDraft)}</textarea><button class="send" aria-label="发送账单问题" ${busy?'disabled':''}>${icon('up')}</button></div><details class="quiet-help"><summary>AI 使用说明</summary><p>模型可用时会发送样例账单、分析偏好和本段对话。请勿输入支付密码。未连接模型时使用本地计算。</p></details></form></section></aside></div>`;}
async function askAnalysis(message){if(busy||!message.trim())return;busy=true;analysisError='';analysisDraft=message;analysisMobile='chat';billTab='overview';view='bills';render();try{await api('/api/analysis/chat',{message:message.trim()});analysisDraft='';await refresh();}catch(e){analysisError=e.message;}finally{busy=false;render();}}
function bindAnalysis(){
 document.querySelectorAll('[data-analysis-pane]').forEach(b=>b.onclick=()=>{analysisMobile=b.dataset.analysisPane;document.querySelector('.bill-analysis-workspace').dataset.mobilePane=analysisMobile;document.querySelectorAll('[data-analysis-pane]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.analysisPane===analysisMobile)));});
 $('#analysis-records-open')?.addEventListener('click',()=>openLedgerRows(state.analysis.records.map(r=>({...r,title:r.merchant,kind:'expense',source:'bill'})),{title:'原始样例明细 · 2026.10.01—10.12'}));
 $('#analysis-budget-open')?.addEventListener('click',()=>{const a=state.analysis;openDialog({title:'分类与预算依据',wide:true,content:`<section class="panel section-space"><div class="panel-head"><h2>分类与预算依据</h2><span class="muted">预算由你设置</span></div><div class="table-scroll"><table><thead><tr><th>类别</th><th>已支出</th><th>区间预算</th><th>判断依据</th></tr></thead><tbody>${a.rows.map(r=>`<tr><td>${esc(r.name)}</td><td>¥${yuan(r.spent)}</td><td>${r.budget===null?'未设置':`¥${yuan(r.budget)}`}</td><td>${r.budget===null?'不能判断多或少':r.difference>0?`超预算 ¥${yuan(r.difference)}`:r.difference===0?'达到预算':`预算内，余 ¥${yuan(-r.difference)}`}</td></tr>`).join('')}</tbody></table></div></section>`});});

  document.querySelectorAll('[data-ask]').forEach(el=>el.onclick=()=>askAnalysis(el.dataset.ask));
  $('#analysis-form')?.addEventListener('submit',e=>{e.preventDefault();askAnalysis($('#analysis-question').value);});
  $('#analysis-question')?.addEventListener('input',e=>{analysisDraft=e.target.value;});
  $('#analysis-question')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('#analysis-form').requestSubmit();}});
  $('#clear-analysis')?.addEventListener('click',async()=>{if(busy)return;try{await api('/api/analysis/clear',{});analysisDraft='';analysisError='';await refresh();}catch(e){toast(e.message);}});
  document.querySelectorAll('[data-preset]').forEach(el=>el.onclick=()=>{const form=$('#analysis-profile'),careful=el.dataset.preset==='careful';const values={name:careful?'保留资金较多（示例）':'保留资金较少（示例）',reserve:careful?'15000':'5000',upcoming:'4000',budget:careful?'3500':'4500','budget-居住':'2800','budget-餐饮':careful?'250':'500','budget-生活':'400','budget-学习':'150','budget-订阅':'55','budget-交通':'100'};for(const [name,value]of Object.entries(values))form.elements.namedItem(name).value=value;});
  $('#analysis-profile')?.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;try{const data=new FormData(e.target);const cents=name=>{const value=String(data.get(name)||'').trim();if(!value)return null;if(!/^\d+(\.\d{1,2})?$/.test(value))throw new Error('金额请输入非负数字，最多两位小数');const [whole,fraction='']=value.split('.');return Number(whole)*100+Number(fraction.padEnd(2,'0'));};await api('/api/analysis/profile',{name:data.get('name'),reserve:cents('reserve'),upcoming:cents('upcoming'),budget:cents('budget'),categoryBudgets:Object.fromEntries(state.analysis.rows.map(r=>[r.name,cents('budget-'+r.name)]))});await refresh();await askAnalysis('结合我的预算和余额，分析哪些消费偏多、哪些可以调整。');}catch(error){toast(error.message);}});
  document.querySelectorAll('[data-review]').forEach(el=>el.onclick=async()=>{try{await api('/api/analysis/review',{id:el.dataset.review,status:el.dataset.status});await refresh();}catch(e){toast(e.message);}});
  document.querySelectorAll('[data-draft]').forEach(el=>el.onclick=()=>{const a=state.analysis.anomalies.find(a=>a.ids[0]===el.dataset.draft);const rows=state.analysis.records.filter(r=>a.ids.includes(r.id));const text='FinGuard 模拟扣费核对材料\n状态：待核实，未提交商户，未退款\n'+rows.map(r=>`${r.id} | ${r.date} | ${r.merchant} | ¥${yuan(r.cents)}`).join('\n')+'\n用户记录：'+(reviewNames[state.reviews?.[a.ids[0]]?.status]||'待核对')+'\n用户说明：'+(state.reviews?.[a.ids[0]]?.note||'无')+'\n请核对是否对应不同订单、是否已有退款及代扣协议。相同日期与金额不能单独证明错误扣款。';const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='FinGuard-扣费核对材料.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
}
function oldBills(){const report=state.bills;return `<div class="two-col"><section class="panel"><div class="panel-head"><h2>样例区间支出</h2><strong>¥${yuan(report.total)}</strong></div><div class="task-body">${chart(report)}</div></section><section class="panel"><div class="panel-head"><h2>需要核对的交易</h2><span class="pill amber">${report.anomalies.length} 组提醒</span></div><div class="task-body">${report.anomalies.map(a=>`<h3>${esc(a.merchant)} · ¥${yuan(a.cents)}</h3><p class="muted" style="font-size:12px;margin:12px 0">${esc(a.reason)}</p><div class="notice">对应明细：${a.ids.map(esc).join('、')}<br>这是样例检测结果，不代表已确认欺诈或错误。</div>`).join('')}<div class="actions"><button class="secondary" data-nav="subscriptions">查看相关订阅</button><button class="primary" data-prompt="分析本月账单">生成分析记录</button></div></div></section></div><section class="panel section-space"><div class="panel-head"><h2>原始账单明细</h2><small>固定样例 · 不含本次模拟转账回执</small></div><div class="table-scroll"><table><thead><tr><th>明细编号</th><th>日期</th><th>商户</th><th>分类</th><th>金额</th></tr></thead><tbody>${report.records.map(r=>`<tr><td>${r.id}</td><td>${r.date}</td><td>${esc(r.merchant)}</td><td>${esc(r.category)}</td><td>¥${yuan(r.cents)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function subscriptions(){return `${stats()}<div class="sub-grid">${state.subscriptions.map((s,i)=>`<section class="sub-card"><div class="sub-mark">${['♪','☁','▷'][i]}</div><div class="status-line"><h2>${esc(s.name)}</h2><span class="badge ${s.status==='active'?'approval':'success'}">${s.status==='active'?'代扣有效':'已停止'}</span></div><div class="sub-price">¥${yuan(s.cents)} <small>/ 月</small></div><p>下次样例扣费：${s.status==='active'?s.next:'不再自动代扣'}<br>周期线索：8月、9月、10月历史扣费<br><details><summary>扣费依据</summary>${s.evidence.map(esc).join('、')}</details></p><button class="${s.status==='active'?'secondary':'primary'}" data-prompt="停止${esc(s.name)}代扣" ${s.status!=='active'?'disabled':''}>${s.status==='active'?'申请停止代扣':'已停止模拟代扣'}</button></section>`).join('')}</div><div class="notice">取消仅改变模拟银行中的代扣状态。商户订阅合同、权益和退款需要另行核对。此处周期识别基于样例流水；导入账单在独立分析区查看。</div>`;}
function evidence(){const t=task()||state.tasks[0];return `<div class="two-col"><section class="panel"><div class="panel-head"><h2>全部目标 <small> / ${state.tasks.length}</small></h2><a class="mini-link" href="/api/evidence" download>导出证据 JSON ↓</a></div><div class="activity-list">${state.tasks.length?state.tasks.map(activityRow).join(''):'<div class="activity-empty">还没有操作证据。完成一个目标后会自动记录。</div>'}</div></section><section class="panel"><div class="panel-head"><h2>操作时间线</h2>${t?badge(t.status):''}</div><div class="task-body">${t?`<p class="muted" style="font-size:12px;margin-bottom:24px">${esc(t.message)}</p>${t.events.map(e=>`<div class="event"><h3>${esc(e.text)}</h3><small>${new Date(e.time).toLocaleTimeString('zh-CN',{hour12:false})} · ${esc(e.type)}</small><details><summary>查看记录详情</summary><pre>${esc(JSON.stringify(e.details,null,2))}</pre></details></div>`).join('')}`:'<div class="empty-state"><div class="empty-shield">'+icon('log')+'</div><p>每次目标、授权、执行和核对<br>都会留下记录。</p></div>'}</div></section></div><p class="muted" style="font-size:11px;margin-top:18px">本地证据用于演示核对与排错，不具备防篡改或法律存证保证。导出不包含授权凭证或模型密钥。</p>`;}
function revealHomeReply(){const box=document.querySelector('.home-assistant .conversation'),answer=document.getElementById('home-latest-reply');if(!box||!answer)return;box.scrollTop+=answer.getBoundingClientRect().top-box.getBoundingClientRect().top-16;const rect=answer.getBoundingClientRect();if(rect.top<0||rect.top>innerHeight-100)answer.scrollIntoView({block:'center'});}
async function send(message){
 if(busy||!message.trim())return;
 if(fundingIntent(message)){await openFundingAssistant(api,refresh,{message});return;}
 if(/记一笔|记一下|记账|补记|特殊开销/.test(message)){await openExpenseConversation(null,message);return;}
 if(/理财|基金|黄金|申购|赎回|闲钱|资金安排/.test(message)){await openWealthAssistant(api,refresh,{message});return;}
 let billQuestion=false;busy=true;homeChatError='';homeReplyReady=false;homePending=message.trim();view='home';render();const pendingLog=document.querySelector('.home-assistant .conversation');if(pendingLog)pendingLog.scrollTop=pendingLog.scrollHeight;
 try{const t=await api('/api/plan',{message:message.trim(),fault,previousId:selected});
  if(t.fundingAssistant){await openFundingAssistant(api,refresh,{message});return;}
  if(t.wealthAssistant){await openWealthAssistant(api,refresh,{message});return;}
  if(t.bankingPlan){selected=null;await refresh();await reviewBankPlan(t.bankingPlan.id,api,refresh);return;}
  selected=t.id;billQuestion=t.action==='bills'&&t.status==='success';homeReplyReady=true;await refresh();
 }catch(e){homeChatError=e.message;}
 finally{busy=false;homePending='';render();if(task()?.status==='approval')$('#approval-dialog')?.showModal();else if(['blocked','unavailable'].includes(task()?.status)&&['transfer','deposit','cancel'].includes(task()?.action))showPrompt(/余额/.test(task().summary)?'余额不足':'当前操作无法继续',[task().summary,'可用余额 ¥'+yuan(state.balance)]);else if(!document.querySelector('dialog[open]')&&homeReplyReady)requestAnimationFrame(revealHomeReply);}
 if(billQuestion)await askAnalysis(message);
}
async function act(action,value){
 if(action==='new'){selected=null;render();$('#message')?.focus();return;}if(busy)return;let t=task();if(!t)return;
 const auth={...credentials($('#approval-dialog')||document),...budgetAck($('#approval-dialog')||document)};
 if(action==='approve'){
  busy=true;const dialog=$('#approval-dialog');dialog?.setAttribute('aria-busy','true');dialog?.querySelectorAll('button,input,select').forEach(el=>el.disabled=true);
  try{
   const latest=await api('/api/tasks/'+t.id),revised=latest.token!==t.token||JSON.stringify(latest.params)!==JSON.stringify(t.params)||latest.moneyReview?.token!==t.moneyReview?.token;
   const i=state.tasks.findIndex(x=>x.id===t.id);if(i>=0)state.tasks[i]=latest;
   if(latest.status!=='approval'){busy=false;render();showResult(latest.status==='success'?'这笔操作已完成':'操作状态已更新',[latest.summary||'',...(latest.result?.id?['回执：'+latest.result.id]:[])]);refresh().catch(()=>{});return;}
   if(revised){busy=false;render();$('#approval-dialog')?.showModal();toast('操作信息已变化，请重新核对本笔信息。');return;}
   t=latest;
  }catch(e){busy=false;render();toast('核对未完成，尚未提交：'+e.message);return;}
  finally{busy=false;dialog?.removeAttribute('aria-busy');dialog?.querySelectorAll('button,input,select').forEach(el=>el.disabled=false);}
 }
if(action==='approve'&&t.moneyReview?.requiresChoice&&!auth.budgetAck){toast('请先看清预算影响，并选择是否仅本次继续。');return;}if(action==='approve'&&((t.verification?.pin&&!/^\d{6}$/.test(auth.paymentPin))||(t.verification?.totp&&!/^\d{6}$/.test(auth.totp)))){render();$('#approval-dialog')?.showModal();toast('请按当前要求完成本笔验证。');return;}
 busy=true;render();let result,error;
 try{const body=action==='approve'?{token:t.token,...auth}:action==='clarify'?{recipientId:value}:{};result=await api(`/api/tasks/${t.id}/${action}`,body);if(result.status==='pending'){try{result=await api('/api/tasks/'+result.id);}catch{}}}catch(e){error=e.message;if(e.status===409||!e.status||e.status>=500){try{const found=await api('/api/tasks/'+t.id);if(found&&['success','pending','rejected','blocked','expired'].includes(found.status))result=found;}catch{}}}finally{busy=false;if(state){if(result){const i=state.tasks.findIndex(x=>x.id===result.id);if(i>=0)state.tasks[i]=result;}render();}}
 if(error&&!result){showResult('操作未确认',[error,'如提交后发生网络中断，请先查看待办和交易记录，核对结果后再操作。']);return;}
 if(['approve','reconcile','reject'].includes(action)){
 const done=result?.status==='success',receipt=result?.result;
 showResult(done?(t.action==='cancel'?'代扣已停止':t.action==='deposit'?'转入成功':'转账成功'):labels[result?.status]||'结果待核对',[
  result?.summary||'',...(result?.moneyDecision?.choice==='continue-once'?['已记录你选择仅本次继续；原预算和最低保留设置未变。','选择时间：'+new Date(result.moneyDecision.time).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})]:[]),...(t.params?.cents?['金额：¥'+yuan(t.params.cents)]:[]),
  '对象：'+(t.contact?.name||t.subscription?.name||t.params?.source||'本账户'),
  ...(done&&receipt?.id?['完成时间：'+new Date(receipt.time).toLocaleString('zh-CN'),'回执：'+receipt.id]:['尚无已完成回执，请以待办和交易记录为准。'])]);
 }else if(task()?.status==='approval')$('#approval-dialog')?.showModal();
 if(result)refresh().catch(()=>toast('操作结果已保存，账户信息暂未刷新。'));
}


const todayKey=new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'});
let expenseController=null;
let calendarMonth=todayKey.slice(0,7),calendarDay=todayKey,calendarMode='month',contactEdit='',expenseEdit='',goalEdit='';
const planCategories=['居住','餐饮','生活','学习','订阅','交通','其他'];
const cnyInput=v=>String((v||0)/100);
function readMoney(v){if(!/^\d+(\.\d{1,2})?$/.test(String(v)))throw new Error('请输入非负金额，最多两位小数');const [a,b='']=String(v).split('.');return Number(a)*100+Number(b.padEnd(2,'0'));}
function rangeField(label,name,cents,max=20000){return `<label class="slider-field">${esc(label)}<span class="range-pair"><input type="range" min="0" max="${Math.max(max,Math.ceil(cents/100))}" step="1" value="${cents/100}" data-range="${esc(name)}" aria-label="${esc(label)}滑条"><input type="number" min="0" max="1000000" step="0.01" name="${esc(name)}" value="${cnyInput(cents)}" required aria-label="${esc(label)}金额"><span>元</span></span></label>`;}
function contactsView(){return `<section class="panel"><div class="panel-head"><h2>收款人通讯录</h2><span class="pill">仅模拟账户</span></div><div class="task-body"><input id="contact-search" aria-label="搜索收款人" placeholder="搜索姓名、称呼或账户尾号"><div class="contact-grid">${state.contacts.map(c=>`<article class="contact-card" data-contact-text="${esc(c.name+c.alias+c.tail)}"><h3>${esc(c.name)}</h3><p>${esc(c.alias||'未设置称呼')} · 尾号 ${esc(c.tail)}</p><p class="muted">${esc(c.description)}</p><div class="actions"><button class="primary" data-contact-pay="${c.id}">向他转账</button><button class="secondary" data-contact-edit="${c.id}">编辑</button></div></article>`).join('')}</div><h3>${contactEdit?'编辑收款人':'添加模拟收款人'}</h3><p class="muted">称呼由你指定，例如“爸爸”。只保存模拟账户尾号，不接入真实银行。</p><form id="contact-form" class="feature-form"><label>姓名<input name="name" maxlength="30" required></label><label>称呼<input name="alias" maxlength="20" placeholder="例如 爸爸"></label><label>模拟账户尾号<input name="tail" pattern="[0-9]{4}" maxlength="4" required></label><label>备注<input name="description" maxlength="50"></label><button class="primary">保存收款人</button><button type="button" class="secondary" id="contact-new">新建</button></form></div></section>`;}
function depositView(){return `<section class="panel"><div class="panel-head"><h2>模拟转入资金</h2><span class="pill amber">不会充值真实资金</span></div><form id="deposit-form" class="task-body feature-form"><p>余额 ¥${yuan(state.balance)}。提交后先核对确认卡，确认前余额不变。</p><label>来源账户<select name="source"><option>模拟工资卡</option><option>模拟储蓄卡</option></select></label><label>转入金额（元）<input name="amount" type="number" min="0.01" max="1000000" step="0.01" required></label><button class="primary">核对模拟转入</button></form></section>${ordersView()}`;}
function ordersView(){return `<section class="panel section-space"><div class="panel-head"><h2>资金操作记录</h2></div><div class="task-body">${state.orders.filter(o=>['deposit','transfer'].includes(o.action)).slice().reverse().map(o=>`<div class="detail-row"><span>${o.action==='deposit'?'转入':'转出'}<details><summary>回执详情</summary>${esc(o.id)}</details><small class="muted"> ${new Date(o.time).toLocaleString('zh-CN')}</small></span><strong>${o.action==='deposit'?'+':'−'}¥${yuan(o.params.cents)}</strong></div>`).join('')||'<p class="muted">暂无资金操作记录</p>'}</div></section>`;}
function planningView(){const p=state.personal.plan;return `<section class="panel"><div class="panel-head"><h2>我的资金安排</h2><span class="pill">规划不移动资金</span></div>${budgetEditorHTML(p)}</section>${savingsEntryHTML(state.personal.savings)}${expenseForm()}<p class="muted section-space">下面是兼容旧版的10月1—12日样例分析设置，与上方月度计划分开。</p>${preferences()}`;}
function expenseForm(){return '<section class="expense-entry" id="expense-editor"><div><h2>记一笔开销</h2><p class="muted">告诉 AI 发生了什么，确认后保存。</p></div><button type="button" class="primary" data-open-expense>对话记账</button></section>';}
async function openExpenseConversation(editId,message){const d=openDialog({id:'expense-dialog',title:editId?'修改开销记录':'对话记账',wide:true,content:'<div id="expense-chat-host" class="expense-chat"></div>'});const controller=await mountExpenseChat(d.querySelector('#expense-chat-host'),api,{date:calendarDay,onSaved:refresh});expenseController=Promise.resolve(controller);if(editId||message)await controller?.start(editId||undefined);if(message)await controller?.send(message);return d;}
function openOrders(){const items=state.personal.ledger.filter(r=>['order'].includes(r.source));return openLedgerRows(items,{title:'资金操作记录'});}
function openPending(){const d=openDialog({id:'pending-dialog',title:'待我处理',wide:true,content:pendingView()});d.querySelectorAll('[data-bank-plan]').forEach(b=>b.onclick=()=>{d.close();reviewBankPlan(b.dataset.bankPlan,api,refresh).catch(e=>showResult('暂时无法读取',[e.message]));});d.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{selected=b.dataset.task;d.close();render();if(task()?.status==='approval')$('#approval-dialog')?.showModal();});return d;}
async function prepareDeposit(amount,source){const created=await api('/api/deposit',{cents:readMoney(amount),source}),t=created.verification?created:await api('/api/tasks/'+created.id);selected=t.id;state.tasks=[t,...state.tasks.filter(x=>x.id!==t.id)];return t;}
function openDeposit(){const d=openDialog({id:'deposit-dialog',title:'转入资金',content:depositView().split('<section class="panel section-space">')[0]});const form=d.querySelector('#deposit-form');form.onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const b=form.querySelector('button');b.disabled=true;let prepared=false;try{const f=new FormData(form);await prepareDeposit(f.get('amount'),f.get('source'));prepared=true;d.close();}catch(err){showResult('转入尚未确认',[err.message]);}finally{busy=false;if(form.isConnected)b.disabled=false;if(prepared){render();$('#approval-dialog')?.showModal();}}};return d;}
function plannedRows(){return [...state.personal.expenses.filter(e=>e.status==='planned'),...state.subscriptions.filter(s=>s.status==='active').map(s=>({id:s.id,date:s.next,title:s.name,cents:s.cents,subscription:true}))];}
function calendarView(){return calendarHTML(state,calendarMonth,calendarDay,calendarMode,plannedRows())+`<details class="section-space"><summary>管理手工补记与计划事项</summary>${state.personal.expenses.filter(e=>e.date.startsWith(calendarMonth)).map(e=>`<p>${esc(e.date+' '+e.title)} · ${{planned:'计划中',actual:'已记录',cancelled:'已取消'}[e.status]} <button class="secondary" data-expense-edit="${e.id}">编辑</button></p>`).join('')||'<p>本月暂无手工事项。</p>'}</details>`+expenseForm();}
function approvalDialog(t){if(!t||t.status!=='approval')return '';const deposit=t.action==='deposit',transfer=t.action==='transfer';return `<dialog id="approval-dialog" aria-labelledby="approval-title"><form method="dialog"><button class="dialog-close" aria-label="暂不处理">×</button></form><div class="dialog-body"><span class="eyebrow">请你决定 · 模拟操作</span><h2 id="approval-title">${deposit?'确认转入资金':transfer?'核对这笔转账':'确认停止代扣'}</h2><p class="modal-amount">${deposit||transfer?'¥'+yuan(t.params.cents):esc(t.subscription?.name)}</p><p class="modal-target">${deposit?esc(t.params.source):transfer?esc(t.contact?.name)+' · 尾号 '+esc(t.contact?.tail):'停止后不再产生此项模拟续费；不会自动退款。'}</p><p class="muted">${deposit?'转入后模拟余额 ¥'+yuan(state.balance+t.params.cents):transfer?'转账后模拟余额 ¥'+yuan(state.balance-t.params.cents):'商户合同与权益需另行核对。'}</p><p class="expiry-note">仅授权本次对象与金额，${new Date(t.expiresAt).toLocaleTimeString('zh-CN')} 前有效。</p>${moneyReviewHTML(t.moneyReview)}${transfer?'<details class="review-use-editor"><summary>'+esc(purposeName(t.params))+' · 可调整统计用途</summary>'+useFields(t.params)+'</details>':''}${pinField(t.verification)}<div class="actions"><button class="secondary" data-action="reject" ${busy?'disabled':''}>取消操作</button><button class="primary" data-action="approve" ${busy?'disabled':''}>${busy?'正在处理…':deposit?'确认转入 ¥'+yuan(t.params.cents):transfer?'确认转账 ¥'+yuan(t.params.cents):'确认停止代扣'}</button></div><p class="muted">关闭窗口可稍后处理，不会执行。</p></div></dialog>`;}
function bindFeatures(){
 bindSavingsEntry(document,api,refresh);
 document.querySelector('[data-open-imports]')?.addEventListener('click',()=>{const d=openDialog({id:'import-dialog',title:'导入账单',wide:true,content:'<div id="imports-root"></div>'});mountImports(d.querySelector('#imports-root'),api).catch(e=>showResult('账单导入暂不可用',[e.message]));d.addEventListener('close',()=>syncLedger(true));});

 document.querySelector('[data-open-transfer]')?.addEventListener('click',()=>{const d=openDialog({id:'transfer-entry-dialog',title:'转账',wide:true,content:'<nav class="section-navigation transfer-tools" aria-label="转账工具"><a href="/banking.html#scheduled">定时转账</a><a href="/banking.html#aa">AA分摊</a><a href="/banking.html#appointments">已预约</a></nav><div data-transfer-content>正在读取账户…</div>'});api('/api/banking').then(fresh=>{if(d.isConnected)mountTransfer(d.querySelector('[data-transfer-content]'),fresh,api,()=>{d.close();return refresh();});}).catch(e=>{if(d.isConnected)d.querySelector('[data-transfer-content]').textContent=e.message;});});

 document.querySelector('[data-open-expense]')?.addEventListener('click',()=>openExpenseConversation());
 $('#contact-search')?.addEventListener('input',e=>document.querySelectorAll('[data-contact-text]').forEach(x=>x.hidden=!x.dataset.contactText.includes(e.target.value)));
 const fill=(form,obj)=>{for(const [k,v]of Object.entries(obj)){const el=form.elements.namedItem(k);if(el)el.value=v??'';}};
 document.querySelectorAll('[data-contact-edit]').forEach(el=>el.onclick=()=>{contactEdit=el.dataset.contactEdit;fill($('#contact-form'),state.contacts.find(c=>c.id===contactEdit));$('#contact-form').scrollIntoView({block:'center'});});
 $('#contact-new')?.addEventListener('click',()=>{contactEdit='';$('#contact-form').reset();});
 document.querySelectorAll('[data-contact-pay]').forEach(el=>el.onclick=()=>{const c=state.contacts.find(c=>c.id===el.dataset.contactPay);send('给'+c.name+'转账');});
 document.querySelectorAll('[data-range]').forEach(el=>{const input=el.closest('form').elements.namedItem(el.dataset.range);el.oninput=()=>{input.value=el.value;previewBudget();};input.oninput=()=>{el.max=Math.max(Number(el.max),Number(input.value));el.value=input.value;previewBudget();};});
 bindBudgetEditor(document,{plan:state.personal.plan,ledger:state.personal.ledger,api,onSaved:async()=>{await refresh();toast('预算已保存');},onCancel:()=>render()});
 function previewBudget(){}
 async function submit(form,path,build,after=()=>{}){form?.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;busy=true;const btn=form.querySelector('button.primary');btn.disabled=true;try{const b=build(new FormData(form));await api(path,b);after();await refresh();toast('已保存');}catch(error){toast(error.message);}finally{busy=false;render();}});}
 submit($('#contact-form'),'/api/personal/contact',f=>({id:contactEdit||undefined,...Object.fromEntries(f)}),()=>contactEdit='');

 document.querySelectorAll('[data-expense-edit]').forEach(el=>el.onclick=async()=>{await openExpenseConversation(el.dataset.expenseEdit);});
 $('#calendar-month')?.addEventListener('change',e=>{if(!e.target.value)return;calendarMonth=e.target.value;calendarDay=calendarMonth+'-01';render();});
 $('#calendar-mode')?.addEventListener('change',e=>{calendarMode=e.target.value;render();});
 document.querySelectorAll('[data-day]').forEach(el=>el.onclick=()=>{calendarDay=el.dataset.day;render();openDay(state,calendarDay,plannedRows());});
 $('#deposit-form')?.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;busy=true;try{const f=new FormData(e.target);await prepareDeposit(f.get('amount'),f.get('source'));view='home';}catch(err){toast(err.message);}finally{busy=false;render();$('#approval-dialog')?.showModal();}});
 $('#open-approval')?.addEventListener('click',()=>$('#approval-dialog')?.showModal());
 const dialog=$('#approval-dialog');dialog?.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
}

refresh().then(()=>{if(task()?.status==='approval')$('#approval-dialog')?.showModal();}).catch(e=>{if(e.auth)return;$('#app').innerHTML=`<div class="loading">暂时无法连接本地服务。请重新启动后刷新页面。<p>${esc(e.message)}</p></div>`;});



function displayName(){return state.personal?.profile?.nickname||(state.user?.reviewSpace?'独立体验':state.user?.username)||'测试用户';}
function profileAvatar(){return state.personal?.profile?.avatar==='star'?'✦':state.personal?.profile?.avatar==='leaf'?'❧':esc(displayName().slice(0,1).toUpperCase());}
function balanceStrip(){return `<section class="balance-strip"><div><span class="eyebrow">模拟账户 · 可用余额</span><div class="balance-amount"><small>¥</small>${yuan(state.balance)}</div><span class="muted">模拟账户 · 尾号 2026</span><div class="balance-context"><span>最低保留金额<strong>${state.personal.plan.reserve==null?'未设置':'¥'+yuan(state.personal.plan.reserve)}</strong></span><span>储蓄已存<strong>¥${yuan(state.personal.savings?.total||0)}</strong></span><span>有效订阅 / 周期<strong>¥${yuan(state.subscriptions.filter(s=>s.status==='active').reduce((n,s)=>n+s.cents,0))}</strong></span></div></div><div class="balance-actions"><button class="primary" type="button" data-open-transfer>转账 ↗</button><button class="secondary" data-nav="deposit">转入 ↓</button><button class="mini-link" type="button" data-open-savings>储蓄空间 →</button><button class="mini-link" data-nav="records">交易记录 →</button></div></section>`;}
function upcomingView(){const rows=plannedRows().filter(r=>r.date>=todayKey).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,4);return `<section class="panel section-space"><div class="panel-head"><h2>接下来的安排</h2><button class="mini-link" data-nav="calendar">查看日历 →</button></div><div class="task-body">${rows.length?rows.map(r=>`<div class="detail-row"><span>${esc(r.title)}<small class="muted"> · ${esc(r.date)} · ${r.subscription?'已知下次代扣':'计划花费'}</small></span><strong>¥${yuan(r.cents)}</strong></div>`).join(''):'<p class="muted">暂无未来安排。可以在日历中记一笔计划花费。</p>'}</div></section>`;}
function profileView(){return `<section class="panel profile-hero"><span class="avatar large-avatar">${profileAvatar()}</span><div><h2>${esc(displayName())}</h2><p class="muted">账号 ${esc(state.user.username)} · 独立模拟空间</p></div><button class="secondary" id="edit-profile">编辑资料</button></section><div class="profile-shortcuts"><button class="panel" data-plan-section="budget-form"><span>月度预算</span><strong>${state.personal.plan.allocationMode==='balanced'?'¥'+yuan(state.personal.plan.totalBudget):state.personal.plan.budget?'¥'+yuan(state.personal.plan.budget):'尚未设置'}</strong><small>调整预算与保留余额 →</small></button><button class="panel" data-open-savings><span>储蓄空间</span><strong>¥${yuan(state.personal.savings?.total||0)}</strong><small>存入、取回与目标管理 →</small></button><button class="panel" data-plan-section="expense-editor"><span>特殊开销</span><strong>${state.personal.expenses.filter(x=>x.status==='planned').length} 项计划</strong><small>记录计划与实际支出 →</small></button></div><section class="panel section-space"><div class="panel-head"><h2>账户安全</h2></div><div class="task-body"><p class="muted">修改登录密码后，所有设备需要重新登录。登录密码与支付授权不同。</p><button class="secondary" id="edit-password">修改登录密码</button><button class="text-button" id="profile-logout">退出登录</button></div></section><dialog id="profile-dialog"><div class="dialog-body"><button class="dialog-close" data-close-profile aria-label="关闭">×</button><h2>编辑个人资料</h2><form id="profile-form" class="feature-form"><label>昵称<input name="nickname" maxlength="24" value="${esc(displayName())}" required></label><label>头像样式<select name="avatar">${[['initial','昵称首字'],['star','星芒'],['leaf','叶片']].map(([k,n])=>`<option value="${k}" ${state.personal.profile?.avatar===k?'selected':''}>${n}</option>`).join('')}</select></label><button class="primary">保存资料</button><p class="form-error" role="alert"></p></form></div></dialog><dialog id="password-dialog"><div class="dialog-body"><button class="dialog-close" data-close-password aria-label="关闭">×</button><h2>修改登录密码</h2><form id="password-form" class="feature-form"><label>当前密码<input name="currentPassword" type="password" autocomplete="current-password" maxlength="128" required></label><label>新密码（12—128个字符）<input name="newPassword" type="password" autocomplete="new-password" minlength="12" maxlength="128" required></label><label>再次输入新密码<input name="confirm" type="password" autocomplete="new-password" minlength="12" maxlength="128" required></label>${otpField()}<a href="/banking.html#security">先绑定手机验证器</a><button class="primary">修改并重新登录</button><p class="form-error" role="alert"></p></form></div></dialog>`;}
function bindProfile(){
 document.querySelectorAll('[data-plan-section]').forEach(el=>el.onclick=()=>{view='planning';render();document.getElementById(el.dataset.planSection)?.scrollIntoView({block:'start',behavior:'smooth'});});
 $('#edit-profile')?.addEventListener('click',()=>$('#profile-dialog').showModal());$('#edit-password')?.addEventListener('click',()=>$('#password-dialog').showModal());
 $('[data-close-profile]')?.addEventListener('click',()=>$('#profile-dialog').close());$('[data-close-password]')?.addEventListener('click',()=>$('#password-dialog').close());
 $('#profile-logout')?.addEventListener('click',()=>$('#logout').click());
 $('#profile-form')?.addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const d=new FormData(e.target);await api('/api/personal/profile',{nickname:d.get('nickname'),avatar:d.get('avatar')});await refresh();toast('资料已保存');}catch(err){e.target.querySelector('.form-error').textContent=err.message;}finally{button.disabled=false;}});
 $('#password-form')?.addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const d=new FormData(e.target);if(d.get('newPassword')!==d.get('confirm'))throw Error('两次新密码不一致');await api('/api/auth/password',{currentPassword:d.get('currentPassword'),newPassword:d.get('newPassword'),totp:d.get('totp')});state=null;selected=null;view='home';renderLogin('密码已更新，请使用新密码登录。');}catch(err){e.target.querySelector('.form-error').textContent=err.message;}finally{button.disabled=false;}});
}

function pendingStrip(){const tasks=state.tasks.filter(t=>['approval','clarify','collecting','pending'].includes(t.status)),plans=(state.bankPlans||[]).filter(p=>['approval','paused','invalidated'].includes(p.status));if(!tasks.length&&!plans.length)return '';return `<section class="pending-strip ${tasks.some(t=>t.status==='pending')||plans.some(p=>p.status==='paused')?'urgent':tasks.length+plans.length?'attention':'clear'}" aria-label="待办提醒"><strong>待我处理 ${tasks.length+plans.length}</strong><span>待确认 ${tasks.filter(t=>t.status==='approval').length+plans.filter(p=>p.status==='approval').length} · 待补充 ${tasks.filter(t=>['clarify','collecting'].includes(t.status)).length} · 待核对 / 暂停 ${tasks.filter(t=>t.status==='pending').length+plans.filter(p=>p.status!=='approval').length}</span><button class="secondary" data-nav="pending">查看待办</button></section>`;}

// Read-only updates never interrupt an edit or an authorization dialog.
let syncingLedger=false;
async function syncLedger(force=false){
 if(!state||busy||syncingLedger||!['home','bills','calendar'].includes(view)||document.hidden)return;
 if(document.querySelector('.account-menu[open]')||document.querySelector('[data-expense-busy=true]')||document.querySelector('dialog[open]')||(!force&&document.activeElement?.matches?.('input,textarea,select')))return;
 const user=state.user?.id,atView=view;syncingLedger=true;
 try{const next=await api('/api/state');if(!state||state.user?.id!==user||view!==atView||busy)return;
 if(next.user?.id!==user){state=next;selected=null;render();return;}
 const changed=JSON.stringify([state.personal?.ledger,state.personal?.expenses,state.personal?.budget,state.balance,state.bankPlans,state.cashflow?.key,state.funding?.progress])!==JSON.stringify([next.personal?.ledger,next.personal?.expenses,next.personal?.budget,next.balance,next.bankPlans,next.cashflow?.key,next.funding?.progress]);
 if(!document.querySelector('dialog[open]')&&!document.activeElement?.matches?.('input,textarea,select')&&(changed||force)){state=next;render();}
 const label=document.querySelector('#ledger-sync');if(label)label.textContent='已更新 '+new Date().toLocaleTimeString('zh-CN');
 }catch(e){const label=document.querySelector('#ledger-sync');if(label)label.textContent='更新失败，当前为上次记录';if(force&&!e.auth)toast(e.message);}finally{syncingLedger=false;}
}
window.setInterval?.(()=>syncLedger(),10000);
window.addEventListener?.('focus',()=>syncLedger(true));
window.addEventListener?.('pageshow',()=>syncLedger(true));
document.addEventListener?.('visibilitychange',()=>{if(!document.hidden)syncLedger(true);});

bindPaymentRecovery(api,()=>refresh());

bindSecurityDialogs(api);



